def valid(number):
    digits = number.replace(" ", "")

    if len(digits) < 2 or any(c < "0" or c > "9" for c in digits):
        return False

    total = 0
    parity = len(digits) % 2

    for i, char in enumerate(digits):
        value = ord(char) - ord("0")
        if i % 2 == parity:
            value *= 2
            if value > 9:
                value -= 9
        total += value

    return total % 10 == 0
